head.script:
scwin.init = function() {
    var jsonData = [{
            "col2": "접수등록",
            "col3": "400"
        },
        {
            "col2": "가입확정",
            "col3": "500"
        },
        {
            "col2": "가입증서발급",
            "col3": "200"
        },
        {
            "col2": "지급심사",
            "col3": "100"
        },
        {
            "col2": "지급내역조회",
            "col3": "55"
        },
        {
            "col2": "신청내역조회",
            "col3": "555"
        },
        {
            "col2": "증서재발급",
            "col3": "22"
        },
        {
            "col2": "해지심사",
            "col3": "23"
        },
        {
            "col2": "111",
            "col3": "222"
        },
        {
            "col2": "222",
            "col3": "244"
        }
    ];
    dataList2.setJSON(jsonData);
    fusionchart1.configure({
        "ChartNoDataText": "데이타가 없습니다.1"
    });
    fusionchart2.configure({
        "ChartNoDataText": "데이타가 없습니다.2"
    });
    fusionchart3.configure({
        "ChartNoDataText": "데이타가 없습니다.3"
    });
    fusionchart3.setChartColumnRef("data:dataList2", "col2", "[['col3']]");
};
scwin.onpageunload = function() {};
scwin.dataList2_ondataload = function() {
    //debugger;
    //var fc = fusionchart3.fc();
    //if($p.getComponentById(fusionchart3.getDataListInfo().id).getTotalRow() == 0) fc.setJSONData({});
};
scwin.trigger1_onclick = function(e) {
    dataList2.setJSON({});
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getObjById('fc_'+$p.id+'fusionchart2').innerText == '데이타가 없습니다.2';
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
	scwin.init()
}
